"""Pure, strict v1 memory contract; supplier prose is never a runtime instruction.

Snapshots are canonical JSON, at most 64 KiB. Evidence has exactly evidence_id,
kind, field, direction, value and citation. Statements have a direction and null
value; observed offers have a bounded integer value and null direction. Citations
have exactly run_id/campaign_id (one non-null), attempt_id, supplier, message_index,
message_sha256, arena_url, environment, case_id and session_id. IDs hash their
canonical content. Original-message resolution is the lab MemoryStore's job.
Lessons contain only the allowlisted action vocabulary and supporting evidence IDs.
"""

import hashlib
import json
import re
from urllib.parse import urlsplit

MAX_MEMORY_BYTES = 65536
MAX_EVIDENCE = 512
MAX_COHORT = 1000
FIELDS = {"contract_months": 36, "payment_days": 120}
ENVIRONMENTS = {"simulator", "sandbox", "practice"}
SNAPSHOT_FIELDS = {
    "schema_version",
    "snapshot_id",
    "arena_url",
    "environment",
    "source_cases",
    "source_suppliers",
    "source_sessions",
    "lessons",
    "evidence",
}
CITATION_FIELDS = {
    "run_id",
    "campaign_id",
    "attempt_id",
    "supplier",
    "message_index",
    "message_sha256",
    "arena_url",
    "environment",
    "case_id",
    "session_id",
}


def canonical_json(value) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def content_id(value) -> str:
    return hashlib.sha256(canonical_json(value).encode()).hexdigest()


def identifier(value) -> bool:
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,239}", value) is not None


def normalize_arena(value: str) -> str:
    if not isinstance(value, str) or len(value) > 2048:
        raise ValueError("invalid arena origin")
    url = urlsplit(value)
    if (
        url.scheme not in {"http", "https"}
        or not url.hostname
        or url.username
        or url.password
        or url.query
        or url.fragment
        or url.path not in {"", "/"}
    ):
        raise ValueError("invalid arena origin")
    host = url.hostname.lower()
    if ":" in host:
        host = f"[{host}]"
    port = url.port
    suffix = "" if port is None or port == {"http": 80, "https": 443}[url.scheme] else f":{port}"
    return f"{url.scheme}://{host}{suffix}"


def supplier_author_matches(sender, supplier_id) -> bool:
    """Match the actual arena author: exact supplier ID or sales@<ID suffix>.

    Arena messages use sales@70110 for sup:70110. Generic sales/supplier labels,
    missing authors, buyer text and another supplier's address are insufficient.
    """
    return (
        identifier(supplier_id)
        and isinstance(sender, str)
        and sender != "buyer"
        and sender
        in {
            supplier_id,
            "sales@" + supplier_id.split(":", 1)[-1],
        }
    )


def _exact(value, fields):
    if not isinstance(value, dict) or set(value) != fields:
        raise ValueError("unexpected memory fields")


def _collection(value, *, maximum, key=lambda item: item, minimum=0):
    if not isinstance(value, list) or not minimum <= len(value) <= maximum:
        raise ValueError("invalid memory collection size")
    keys = [key(item) for item in value]
    if keys != sorted(set(keys)):
        raise ValueError("memory collections must be sorted and unique")


def _digest(value):
    if not isinstance(value, str) or re.fullmatch(r"[a-f0-9]{64}", value) is None:
        raise ValueError("invalid content ID")


def derive_lessons(evidence: list[dict]) -> list[dict]:
    """Abstain for conflicts or less than three suppliers across two cases."""
    lessons = []
    for field in sorted(FIELDS):
        statements = [e for e in evidence if e["kind"] == "supplier_statement" and e["field"] == field]
        directions = {e["direction"] for e in statements}
        if len(directions) != 1:
            continue
        if len({e["citation"]["supplier"] for e in statements}) < 3:
            continue
        if len({e["citation"]["case_id"] for e in statements}) < 2:
            continue
        direction = next(iter(directions))
        lessons.append(
            {
                "lesson_id": f"preference:{field}:{direction}",
                "field": field,
                "direction": direction,
                "evidence_ids": sorted(e["evidence_id"] for e in statements),
            }
        )
    return sorted(lessons, key=lambda lesson: lesson["lesson_id"])


def validate_memory(snapshot: dict) -> dict:
    """Validate hashes, exact JSON schema, cohorts, support and contradiction abstention.

    Returns a detached JSON object. Does not consult a lab, execute source text,
    normalize content after hashing or permit arbitrary additional instructions.
    """
    try:
        return _validate_memory(snapshot)
    except (TypeError, KeyError, OverflowError, RecursionError) as error:
        raise ValueError("invalid memory snapshot") from error


def _validate_memory(snapshot):
    _exact(snapshot, SNAPSHOT_FIELDS)
    encoded = canonical_json(snapshot)
    if len(encoded.encode()) > MAX_MEMORY_BYTES:
        raise ValueError("memory snapshot too large")
    if type(snapshot["schema_version"]) is not int or snapshot["schema_version"] != 1:
        raise ValueError("invalid memory schema version")
    _digest(snapshot["snapshot_id"])
    if snapshot["snapshot_id"] != content_id({k: v for k, v in snapshot.items() if k != "snapshot_id"}):
        raise ValueError("memory content ID mismatch")
    if normalize_arena(snapshot["arena_url"]) != snapshot["arena_url"]:
        raise ValueError("memory arena must be normalized")
    if snapshot["environment"] not in ENVIRONMENTS:
        raise ValueError("invalid memory environment")
    for name in ("source_cases", "source_suppliers", "source_sessions"):
        _collection(snapshot[name], maximum=MAX_COHORT, minimum=0 if name == "source_suppliers" else 1)
        if any(not identifier(item) for item in snapshot[name]):
            raise ValueError("invalid memory provenance identity")
    _collection(snapshot["evidence"], maximum=MAX_EVIDENCE, key=lambda e: e["evidence_id"])
    for evidence in snapshot["evidence"]:
        _exact(evidence, {"evidence_id", "kind", "field", "direction", "value", "citation"})
        _digest(evidence["evidence_id"])
        if evidence["evidence_id"] != content_id({k: v for k, v in evidence.items() if k != "evidence_id"}):
            raise ValueError("evidence content ID mismatch")
        if evidence["field"] not in FIELDS:
            raise ValueError("unsupported memory field")
        if evidence["kind"] == "supplier_statement":
            if evidence["direction"] not in {"higher", "lower"} or evidence["value"] is not None:
                raise ValueError("invalid supplier statement")
        elif evidence["kind"] == "observed_offer":
            value = evidence["value"]
            if (
                evidence["direction"] is not None
                or type(value) is not int
                or not 0 <= value <= FIELDS[evidence["field"]]
            ):
                raise ValueError("invalid observed offer")
        else:
            raise ValueError("unsupported memory evidence")
        citation = evidence["citation"]
        _exact(citation, CITATION_FIELDS)
        if (citation["run_id"] is None) == (citation["campaign_id"] is None):
            raise ValueError("citation requires exactly one source record")
        for name in ("run_id", "campaign_id", "attempt_id", "supplier", "case_id", "session_id"):
            if citation[name] is not None and not identifier(citation[name]):
                raise ValueError("invalid citation identity")
            if name not in {"run_id", "campaign_id"} and citation[name] is None:
                raise ValueError("missing citation identity")
        if type(citation["message_index"]) is not int or not 0 <= citation["message_index"] < 5000:
            raise ValueError("invalid message index")
        _digest(citation["message_sha256"])
        if citation["arena_url"] != snapshot["arena_url"] or citation["environment"] != snapshot["environment"]:
            raise ValueError("citation differs from discovery scope")
        for key, cohort in (
            ("case_id", "source_cases"),
            ("supplier", "source_suppliers"),
            ("session_id", "source_sessions"),
        ):
            if citation[key] not in snapshot[cohort]:
                raise ValueError("citation absent from discovery cohort")
    _collection(snapshot["lessons"], maximum=4, key=lambda lesson: lesson["lesson_id"])
    eligible = {lesson["lesson_id"]: lesson for lesson in derive_lessons(snapshot["evidence"])}
    for lesson in snapshot["lessons"]:
        _exact(lesson, {"lesson_id", "field", "direction", "evidence_ids"})
        _collection(lesson["evidence_ids"], maximum=MAX_EVIDENCE, minimum=3)
        if lesson != eligible.get(lesson["lesson_id"]):
            raise ValueError("lesson lacks diverse consistent supplier evidence")
    return json.loads(encoded)
"""Complete-sample comparison policy; narrative findings never affect eligibility."""

import math
import statistics


def default_suite(arena_url="https://arena.tacto.ai", environment="sandbox"):
    return dict(
        suite_id=f"d01-d02-{environment}-serial-v1",
        cases=["case:D01", "case:D02"],
        repetitions=3,
        runner="serial",
        arena_url=arena_url,
        environment=environment,
        data={},
        max_sessions=12,
        policy=dict(version="v1", min_gain=1.0, max_case_regression=2.0, min_win_fraction=2 / 3),
    )


def evaluate_campaign(suite, baseline, candidate, attempts):
    gates, gaps = [], []

    def gate(name, passed, detail):
        gates.append(dict(id=name, passed=bool(passed), detail=detail))
        if not passed:
            gaps.append(name)

    gate(
        "checkpoints",
        all(
            c.get("published") is True and c.get("runner") == suite["runner"] and c.get("data") == suite["data"]
            for c in (baseline, candidate)
        ),
        "Published checkpoints and identical declared runner/data required",
    )
    planned = {
        (arm, case, repeat)
        for arm in ("baseline", "candidate")
        for case in suite["cases"]
        for repeat in range(1, suite["repetitions"] + 1)
    }
    indexed = {(a.get("arm"), a.get("case_id"), a.get("repeat")): a for a in attempts}
    valid = len(indexed) == len(attempts) and set(indexed) == planned
    valid = valid and all(
        a.get("status") == "completed"
        and a.get("result", {}).get("ended") is True
        and type(a.get("score")) in (int, float)
        and math.isfinite(a["score"])
        and 0 <= a["score"] <= 1
        and ("score" not in a.get("result", {}) or a["result"]["score"] == a["score"])
        for a in attempts
    )
    gate("complete_sample", valid and suite["repetitions"] >= 3, "Every planned original outcome required")
    gate(
        "must_haves",
        all(
            type(a.get("result", {}).get("deal")) is bool
            and (not a["result"]["deal"] or a["result"].get("must_haves_ok") is True)
            for a in attempts
            if a.get("arm") == "candidate"
        ),
        "Every candidate deal complies",
    )
    timeout_valid = all(type(a.get("timeouts")) is int and a["timeouts"] >= 0 for a in attempts)
    gate("timeout_evidence", timeout_valid, "Complete known timeout counts required")
    totals = {}
    for arm in ("baseline", "candidate"):
        counts = [a.get("timeouts") for a in attempts if a.get("arm") == arm]
        totals[arm] = sum(counts) if all(type(n) is int and n >= 0 for n in counts) else None
    gate("timeouts", timeout_valid and totals["candidate"] <= totals["baseline"], totals)
    cases, repeats, metrics = [], [], dict(gain=None, timeouts=totals, sample_size=len(attempts))
    if valid:
        for case in suite["cases"]:
            row = {"case_id": case}
            for arm in ("baseline", "candidate"):
                scores = [100 * indexed[arm, case, r]["score"] for r in range(1, suite["repetitions"] + 1)]
                row[arm] = dict(mean=statistics.mean(scores), spread=statistics.pstdev(scores), scores=scores)
            row["gain"] = row["candidate"]["mean"] - row["baseline"]["mean"]
            cases.append(row)
        for r in range(1, suite["repetitions"] + 1):
            row = dict(repeat=r)
            for arm in ("baseline", "candidate"):
                row[arm] = statistics.mean(100 * indexed[arm, c, r]["score"] for c in suite["cases"])
            row["gain"] = row["candidate"] - row["baseline"]
            repeats.append(row)
        metrics.update(
            gain=statistics.mean(c["gain"] for c in cases),
            win_fraction=sum(r["gain"] > 0 for r in repeats) / len(repeats),
        )
    gate("gain", valid and metrics["gain"] >= suite["policy"]["min_gain"], metrics["gain"])
    gate("case_regression", valid and all(c["gain"] >= -suite["policy"]["max_case_regression"] for c in cases), cases)
    gate("repeat_wins", valid and metrics["win_fraction"] >= suite["policy"]["min_win_fraction"], repeats)
    return dict(
        eligible=all(g["passed"] for g in gates),
        gates=gates,
        cases=cases,
        repeats=repeats,
        metrics=metrics,
        evidence_gaps=gaps,
    )
"""Immutable, credential-free source checkpoints using a private temporary Git index."""

import hashlib
import json
import math
import os
import re
import subprocess
import tempfile
import uuid
from datetime import UTC, datetime
from pathlib import Path
from urllib.parse import urlsplit

from .models import SECRET_KEYS, check_json

DEFAULTS = dict(anchor=0.12, rounds=5, close_gap=0.005, final_hold_s=40.0, p_walk=0.25)
FIELDS = {
    'schema_version', 'checkpoint_id', 'commit', 'project_path', 'author', 'description',
    'parent_id', 'created_at', 'agent', 'config', 'runner', 'lock_sha256', 'submodules',
    'data', 'harness_version', 'remote', 'ref', 'published',
}


def _git(repo, *args, env=None, raw=False):
    process_env = os.environ.copy()
    for key in ('GIT_INDEX_FILE', 'GIT_DIR', 'GIT_WORK_TREE', 'GIT_CONFIG_COUNT', 'GIT_CONFIG_PARAMETERS'):
        process_env.pop(key, None)
    process_env.update(env or {})
    result = subprocess.run(
        ['git', '-c', 'core.hooksPath=/dev/null', '-C', str(repo), *args],
        env=process_env, capture_output=True,
    )
    if result.returncode:
        # Git stderr can contain remote credentials: never include it in public exceptions.
        raise ValueError(f'Git operation failed: {args[0]}')
    return result.stdout if raw else result.stdout.decode().strip()


def _id(value):
    return isinstance(value, str) and bool(re.fullmatch(r'[a-zA-Z0-9_-]{1,80}', value))


def _relative(value):
    return isinstance(value, str) and bool(value) and not Path(value).is_absolute() and '..' not in Path(value).parts


def _hash(value, size=64):
    return isinstance(value, str) and bool(re.fullmatch(rf'[0-9a-f]{{{size}}}', value))


def _remote(value):
    if value is None:
        return
    if not isinstance(value, str) or not value or len(value) > 2048 or any(c in value for c in '\n\r\0'):
        raise ValueError('invalid remote')
    if '://' in value:
        parsed = urlsplit(value)
        if (parsed.scheme not in {'https', 'ssh', 'file'} or parsed.password
                or (parsed.username and parsed.scheme != 'ssh')
                or parsed.query or parsed.fragment):
            raise ValueError('remote must be credential-free')
    elif '@' in value and re.fullmatch(r'[A-Za-z0-9_-]+@[A-Za-z0-9.-]+:[A-Za-z0-9_./-]+', value):
        return
    elif '@' in value or '?' in value or '#' in value:
        raise ValueError('remote must be credential-free')


def _secrets(value):
    encoded = json.dumps(value, allow_nan=False)
    if any(v in encoded for k, v in os.environ.items() if SECRET_KEYS.search(k) and len(v) >= 8):
        raise ValueError('secret value in public checkpoint')


def resolve_config(config):
    if not isinstance(config, dict) or set(config) - (set(DEFAULTS) | {'meso', 'claims', 'estimates'}):
        raise ValueError('unknown checkpoint config option')
    out = {**DEFAULTS, 'meso': os.environ.get('NEGOTIATOR_MESO') == '1',
           'claims': os.environ.get('NEGOTIATOR_CLAIMS') == '1',
           'estimates': None if os.environ.get('NEGOTIATOR_ESTIMATES') == '1' else {}, **config}
    for key in DEFAULTS:
        value = out[key]
        if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
            raise ValueError('invalid numerical config')
    if type(out['rounds']) is not int or not 1 <= out['rounds'] <= 100:
        raise ValueError('invalid rounds')
    if any(out[key] > 1 for key in ('anchor', 'close_gap', 'p_walk')):
        raise ValueError('invalid fraction')
    if any(type(out[key]) is not bool for key in ('meso', 'claims')):
        raise ValueError('unresolved feature switch')
    if out['estimates'] is not None and not isinstance(out['estimates'], dict):
        raise ValueError('invalid estimates')
    check_json(out)
    _secrets(out)
    return out


def validate_checkpoint(body):
    """Validate untrusted public metadata without Git, disk access or network calls."""
    if not isinstance(body, dict) or set(body) != FIELDS:
        raise ValueError('invalid checkpoint fields')
    try:
        encoded = json.dumps(body, allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise ValueError('checkpoint must contain finite JSON') from exc
    if len(encoded.encode()) > 65536:
        raise ValueError('checkpoint too large')
    if type(body['schema_version']) is not int or body['schema_version'] != 1 or not _id(body['checkpoint_id']):
        raise ValueError('invalid checkpoint identity')
    if not _hash(body['commit'], 40) or not _hash(body['lock_sha256']):
        raise ValueError('invalid commit or lock hash')
    if not _relative(body['project_path']) or type(body['published']) is not bool:
        raise ValueError('invalid checkpoint path or publication')
    if body['parent_id'] is not None and not _id(body['parent_id']):
        raise ValueError('invalid parent')
    for key, limit in [('author', 200), ('description', 4000), ('harness_version', 100)]:
        if not isinstance(body[key], str) or not 1 <= len(body[key]) <= limit:
            raise ValueError(f'invalid {key}')
    if not isinstance(body['created_at'], str) or len(body['created_at']) > 50:
        raise ValueError('invalid timestamp')
    try:
        if datetime.fromisoformat(body['created_at']).tzinfo is None:
            raise ValueError('timestamp requires timezone')
    except (ValueError, TypeError) as exc:
        raise ValueError('invalid timestamp') from exc
    if body['agent'] != 'package' or body['runner'] not in {'serial', 'async'}:
        raise ValueError('unsupported agent or runner')
    if not isinstance(body['config'], dict) or set(body['config']) != set(DEFAULTS) | {'meso', 'claims', 'estimates'}:
        raise ValueError('config must be resolved')
    resolve_config(body['config'])
    if not isinstance(body['data'], dict) or len(body['data']) > 100:
        raise ValueError('invalid data manifest')
    if (body['config']['estimates'] is None or body['config']['claims']) and not body['data']:
        raise ValueError('dossier-dependent features require data manifest')
    for name, entry in body['data'].items():
        if not _id(name) or not isinstance(entry, dict) or set(entry) != {'sha256', 'source'}:
            raise ValueError('invalid data manifest')
        if not _hash(entry['sha256']) or not isinstance(entry['source'], str) or not entry['source']:
            raise ValueError('invalid data hash or source')
        _remote(entry['source'])
    if not isinstance(body['submodules'], dict) or len(body['submodules']) > 100:
        raise ValueError('invalid submodules')
    if any(not _relative(k) or not _hash(v, 40) for k, v in body['submodules'].items()):
        raise ValueError('invalid submodule identity')
    _remote(body['remote'])
    if body['ref'] != f"refs/heads/lab/checkpoints/{body['checkpoint_id']}":
        raise ValueError('invalid checkpoint ref')
    if body['published'] and body['remote'] is None:
        raise ValueError('published checkpoint requires remote')
    _secrets(body)
    return json.loads(encoded)


def _root(repo, root=None):
    common = Path(_git(repo, 'rev-parse', '--git-common-dir'))
    return Path(root) if root else (common if common.is_absolute() else repo / common) / 'lab/checkpoints'


def _save(checkpoint, root):
    root.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile('w', dir=root, delete=False) as stream:
        json.dump(checkpoint, stream, indent=2, allow_nan=False)
        stream.flush()
        os.fsync(stream.fileno())
        path = Path(stream.name)
    path.replace(root / f"{checkpoint['checkpoint_id']}.json")


def load_checkpoint(checkpoint_id, root):
    if not _id(checkpoint_id):
        raise ValueError('invalid checkpoint identity')
    body = validate_checkpoint(json.loads((Path(root) / f'{checkpoint_id}.json').read_text()))
    if body['checkpoint_id'] != checkpoint_id:
        raise ValueError('checkpoint identity mismatch')
    return body


def _private(path):
    return any(p.startswith('.env') or p in {'.aws', '.codex', '.agents', '.venv', '.lab-checkpoint.json'}
               or re.search(r'(^|[._-])(api[_-]?key|password|tokens?|secrets?|authorization|credentials?)([._-]|$)',
                            p, re.I) for p in Path(path).parts)


def create_checkpoint(project, *, config, agent='package', runner='serial', author, description,
                      parent_id=None, data=None, root=None):
    project = Path(project).resolve()
    repo = Path(_git(project, 'rev-parse', '--show-toplevel'))
    config = resolve_config(config)
    lock = project / 'uv.lock'
    if not lock.is_file():
        raise ValueError('checkpoint requires project uv.lock')
    remotes = _git(repo, 'remote').splitlines()
    remote = _git(repo, 'remote', 'get-url', 'origin') if 'origin' in remotes else None
    _remote(remote)
    submodules = {}
    for line in _git(repo, 'submodule', 'status', '--recursive', raw=True).decode().splitlines():
        if line[0] != ' ':
            raise ValueError('submodule must be initialized at recorded commit')
        sha, path, *_ = line[1:].split()
        if _git(repo / path, 'status', '--porcelain'):
            raise ValueError('dirty submodule')
        submodules[path] = sha
    names = set(_git(repo, 'ls-files', '-z', raw=True).decode().split('\0'))
    names.update(_git(repo, 'ls-files', '--others', '--exclude-standard', '-z', raw=True).decode().split('\0'))
    names.difference_update(_git(repo, 'ls-files', '-ci', '--exclude-standard', '-z', raw=True).decode().split('\0'))
    names.discard('')
    selected = []
    for name in sorted(names):
        if _private(name) or any(name.startswith(p + '/') for p in submodules):
            continue
        path = repo / name
        if path.is_symlink():
            raise ValueError('checkpoint cannot contain symbolic links')
        if path.is_file():
            content = path.read_bytes()
            if any(v.encode() in content for k, v in os.environ.items() if SECRET_KEYS.search(k) and len(v) >= 8):
                raise ValueError('secret value in source')
            selected.append(name)
    checkpoint_id = uuid.uuid4().hex
    with tempfile.TemporaryDirectory() as temp:
        env = {'GIT_INDEX_FILE': str(Path(temp) / 'index')}
        _git(repo, 'read-tree', '--empty', env=env)
        # hash-object avoids clean filters changing the exact runnable source snapshot.
        for name in selected:
            path = repo / name
            sha = _git(repo, 'hash-object', '-w', '--no-filters', '--', name)
