        _collection(snapshot[name], maximum=MAX_COHORT, minimum=0 if name == "source_suppliers" else 1)
        if any(not identifier(item) for item in snapshot[name]):
            raise ValueError("invalid memory provenance identity")
    _collection(snapshot["evidence"], maximum=MAX_EVIDENCE, key=lambda e: e["evidence_id"])
    for evidence in snapshot["evidence"]:
        _exact(evidence, {"evidence_id", "kind", "field", "direction", "value", "citation"})
        _digest(evidence["evidence_id"])
        if evidence["evidence_id"] != content_id({k: v for k, v in evidence.items() if k != "evidence_id"}):
            raise ValueError("evidence content ID mismatch")
        if evidence["field"] not in FIELDS:
            raise ValueError("unsupported memory field")
        if evidence["kind"] == "supplier_statement":
            if evidence["direction"] not in {"higher", "lower"} or evidence["value"] is not None:
                raise ValueError("invalid supplier statement")
        elif evidence["kind"] == "observed_offer":
            value = evidence["value"]
            if (
                evidence["direction"] is not None
                or type(value) is not int
                or not 0 <= value <= FIELDS[evidence["field"]]
            ):
                raise ValueError("invalid observed offer")
        else:
            raise ValueError("unsupported memory evidence")
        citation = evidence["citation"]
        _exact(citation, CITATION_FIELDS)
        if (citation["run_id"] is None) == (citation["campaign_id"] is None):
            raise ValueError("citation requires exactly one source record")
        for name in ("run_id", "campaign_id", "attempt_id", "supplier", "case_id", "session_id"):
            if citation[name] is not None and not identifier(citation[name]):
                raise ValueError("invalid citation identity")
            if name not in {"run_id", "campaign_id"} and citation[name] is None:
                raise ValueError("missing citation identity")
        if type(citation["message_index"]) is not int or not 0 <= citation["message_index"] < 5000:
            raise ValueError("invalid message index")
        _digest(citation["message_sha256"])
        if citation["arena_url"] != snapshot["arena_url"] or citation["environment"] != snapshot["environment"]:
            raise ValueError("citation differs from discovery scope")
        for key, cohort in (
            ("case_id", "source_cases"),
            ("supplier", "source_suppliers"),
            ("session_id", "source_sessions"),
        ):
            if citation[key] not in snapshot[cohort]:
                raise ValueError("citation absent from discovery cohort")
    _collection(snapshot["lessons"], maximum=4, key=lambda lesson: lesson["lesson_id"])
    eligible = {lesson["lesson_id"]: lesson for lesson in derive_lessons(snapshot["evidence"])}
    for lesson in snapshot["lessons"]:
        _exact(lesson, {"lesson_id", "field", "direction", "evidence_ids"})
        _collection(lesson["evidence_ids"], maximum=MAX_EVIDENCE, minimum=3)
        if lesson != eligible.get(lesson["lesson_id"]):
            raise ValueError("lesson lacks diverse consistent supplier evidence")
    return json.loads(encoded)
"""Complete-sample comparison policy; narrative findings never affect eligibility."""

import math
import statistics


def default_suite(arena_url="https://arena.tacto.ai", environment="sandbox"):
    return dict(
        suite_id=f"d01-d02-{environment}-serial-v1",
        cases=["case:D01", "case:D02"],
        repetitions=3,
        runner="serial",
        arena_url=arena_url,
        environment=environment,
        data={},
        max_sessions=12,
        policy=dict(version="v1", min_gain=1.0, max_case_regression=2.0, min_win_fraction=2 / 3),
    )


def evaluate_campaign(suite, baseline, candidate, attempts):
    gates, gaps = [], []

    def gate(name, passed, detail):
        gates.append(dict(id=name, passed=bool(passed), detail=detail))
        if not passed:
            gaps.append(name)

    gate(
        "checkpoints",
        all(
            c.get("published") is True and c.get("runner") == suite["runner"] and c.get("data") == suite["data"]
            for c in (baseline, candidate)
        ),
        "Published checkpoints and identical declared runner/data required",
    )
    planned = {
        (arm, case, repeat)
        for arm in ("baseline", "candidate")
        for case in suite["cases"]
        for repeat in range(1, suite["repetitions"] + 1)
    }
    indexed = {(a.get("arm"), a.get("case_id"), a.get("repeat")): a for a in attempts}
    valid = len(indexed) == len(attempts) and set(indexed) == planned
    valid = valid and all(
        a.get("status") == "completed"
        and a.get("result", {}).get("ended") is True
        and type(a.get("score")) in (int, float)
        and math.isfinite(a["score"])
        and 0 <= a["score"] <= 1
        and ("score" not in a.get("result", {}) or a["result"]["score"] == a["score"])
        for a in attempts
    )
    gate("complete_sample", valid and suite["repetitions"] >= 3, "Every planned original outcome required")
    gate(
        "must_haves",
        all(
            type(a.get("result", {}).get("deal")) is bool
            and (not a["result"]["deal"] or a["result"].get("must_haves_ok") is True)
            for a in attempts
            if a.get("arm") == "candidate"
        ),
        "Every candidate deal complies",
    )
    timeout_valid = all(type(a.get("timeouts")) is int and a["timeouts"] >= 0 for a in attempts)
    gate("timeout_evidence", timeout_valid, "Complete known timeout counts required")
    totals = {}
    for arm in ("baseline", "candidate"):
        counts = [a.get("timeouts") for a in attempts if a.get("arm") == arm]
        totals[arm] = sum(counts) if all(type(n) is int and n >= 0 for n in counts) else None
    gate("timeouts", timeout_valid and totals["candidate"] <= totals["baseline"], totals)
    cases, repeats, metrics = [], [], dict(gain=None, timeouts=totals, sample_size=len(attempts))
    if valid:
        for case in suite["cases"]:
            row = {"case_id": case}
            for arm in ("baseline", "candidate"):
                scores = [100 * indexed[arm, case, r]["score"] for r in range(1, suite["repetitions"] + 1)]
                row[arm] = dict(mean=statistics.mean(scores), spread=statistics.pstdev(scores), scores=scores)
            row["gain"] = row["candidate"]["mean"] - row["baseline"]["mean"]
            cases.append(row)
        for r in range(1, suite["repetitions"] + 1):
            row = dict(repeat=r)
            for arm in ("baseline", "candidate"):
                row[arm] = statistics.mean(100 * indexed[arm, c, r]["score"] for c in suite["cases"])
            row["gain"] = row["candidate"] - row["baseline"]
            repeats.append(row)
        metrics.update(
            gain=statistics.mean(c["gain"] for c in cases),
            win_fraction=sum(r["gain"] > 0 for r in repeats) / len(repeats),
        )
    gate("gain", valid and metrics["gain"] >= suite["policy"]["min_gain"], metrics["gain"])
    gate("case_regression", valid and all(c["gain"] >= -suite["policy"]["max_case_regression"] for c in cases), cases)
    gate("repeat_wins", valid and metrics["win_fraction"] >= suite["policy"]["min_win_fraction"], repeats)
    return dict(
        eligible=all(g["passed"] for g in gates),
        gates=gates,
        cases=cases,
        repeats=repeats,
        metrics=metrics,
        evidence_gaps=gaps,
    )
"}

